import {ArtifactSqliteTableIndex} from "../../🧩️artifact/🗂️table/🟦️.ts";
for(const exact of[true,false])test('direct table index complete literal names '+exact,async()=>{const part=fixture.directSeam,names=exact?part.exactNames:part.foldNames,queries=exact?part.exactQueries:part.foldQueries,positions=exact?part.exactPositions:part.foldPositions;const operation=sqliteOperation(),index=await ArtifactSqliteTableIndex.create(names.map(name=>({name})),operation,exact),oracle=new Map(names.map((name,index)=>[exact?name:name.replace(/[A-Z]/g,c=>c.toLowerCase()),index]));for(let i=0;i<queries.length;i++){const key=exact?queries[i]!:queries[i]!.replace(/[A-Z]/g,c=>c.toLowerCase());expect(oracle.get(key)??-1).toBe(positions[i]);expect(await index.find(queries[i]!)).toBe(positions[i]);}});
for(const specimen of fixture.directSeam.duplicateCases)test('direct table index refuses duplicate comparison '+specimen.exact,async()=>{await expect(ArtifactSqliteTableIndex.create(specimen.names.map(name=>({name})),sqliteOperation(),specimen.exact)).rejects.toMatchObject({kind:'invalidValue'});});
test('direct table index exact slot byte budget and cumulative caller',async()=>{const names=fixture.tableNames.map(name=>({name})),bytes=fixture.tableSlotBytes;for(const maximum of[0,bytes-1])await expect(ArtifactSqliteTableIndex.create(names,sqliteOperation({maxAllocationBytes:maximum}))).rejects.toMatchObject({kind:'ownershipLimit'});const exact=sqliteOperation({maxAllocationBytes:bytes});expect(await(await ArtifactSqliteTableIndex.create(names,exact)).find('q')).toBe(2);expect(exact.ownedBytes).toBe(bytes);await expect(ArtifactSqliteTableIndex.create(names,exact)).rejects.toMatchObject({kind:'ownershipLimit'});const twice=sqliteOperation({maxAllocationBytes:bytes*2});for(let i=0;i<2;i++)expect(await(await ArtifactSqliteTableIndex.create(names,twice)).find('i')).toBe(1);expect(twice.ownedBytes).toBe(bytes*2);await expect(ArtifactSqliteTableIndex.create(names,twice)).rejects.toMatchObject({kind:'ownershipLimit'});});
test('direct table index materialized collision lookup cancellation',async()=>{const part=fixture.directSeam,abort=new AbortController();let armed=false,reached=false;const operation=sqliteOperation({signal:abort.signal,onProgress:event=>{if(armed&&operation.ownedBytes>0&&event.phase==='indexTables'&&event.completed===part.probeFrontier&&event.total===part.collisionSlots){reached=true;abort.abort();}}}),index=await ArtifactSqliteTableIndex.create(part.collisionNames.map(name=>({name})),operation);expect(operation.ownedBytes).toBe(part.collisionSlots*4);armed=true;await expect(index.find(part.collisionNames.at(-1)!)).rejects.toMatchObject({kind:'canceled'});expect(reached).toBe(true);expect(operation.ownedBytes).toBe(part.collisionSlots*4);});
test('direct table index materialized long literal lookup cancellation',async()=>{const part=fixture.directSeam,name=part.longUnit.repeat(part.longRepeat),abort=new AbortController();let armed=false,reached=false;const operation=sqliteOperation({signal:abort.signal,onProgress:event=>{if(armed&&operation.ownedBytes>0&&event.phase==='indexTables'&&event.completed===part.nameFrontier&&event.completed<event.total){reached=true;abort.abort();}}}),index=await ArtifactSqliteTableIndex.create([{name}],operation);armed=true;await expect(index.find(name)).rejects.toMatchObject({kind:'canceled'});expect(reached).toBe(true);});
test('direct table index checked size refuses before mapping impossible census',async()=>{let mapped=false;const hostile=new Proxy([] as {name:string}[],{get(target,key,receiver){if(key==='length')return fixture.directSeam.overflowLength;if(key==='map')return()=>{mapped=true;throw new Error('forbidden census materialization');};return Reflect.get(target,key,receiver);}}),operation=sqliteOperation({maxTables:fixture.directSeam.overflowLength});await expect(ArtifactSqliteTableIndex.create(hostile,operation)).rejects.toMatchObject({kind:'workLimit'});expect(mapped).toBe(false);expect(operation.ownedBytes).toBe(0);});

test('direct literal Unicode and quoted index names independently match SQLite',()=>{const names=fixture.directSeam.foldNames.filter(name=>!name.includes('\0')),db=new Database(':memory:');const quoted=(name:string)=>'"'+name.replaceAll('"','""')+'"';try{for(let i=0;i<names.length;i++){db.exec(`CREATE TABLE ${quoted(names[i]!)} (payload TEXT)`);db.query(`INSERT INTO ${quoted(names[i]!)} VALUES (?)`).run(String(i));}for(let i=0;i<names.length;i++)expect(db.query(`SELECT payload FROM ${quoted(names[i]!.replace(/[A-Z]/g,c=>c.toLowerCase()))}`).get()).toEqual({payload:String(i)});}finally{db.close();}});
